const original = $('Execute Sub-Workflow Trigger').first().json;
const contacts = $input.first().json;

const primaryContact = Array.isArray(contacts) && contacts.length > 0 ? contacts[0] : { phone_number: '254711223344', full_name: 'Manager' };
const secondaryContact = Array.isArray(contacts) && contacts.length > 1 ? contacts[1] : null;

const alertMessage = `🚨 *[ODIN LIVE ESCALATION ALERT]*\n\n` +
  `• Customer: ${original.customer_name || 'Valued Client'} (+${original.customer_phone})\n` +
  `• Reason: ${original.reason || 'Customer requested human assistance'}\n` +
  `• Action: AI agent is pausing for 30 minutes.\n\n` +
  `Please open WhatsApp and take over this chat now.`;

return [{
  json: {
    primary_phone: primaryContact.phone_number,
    primary_name: primaryContact.full_name,
    secondary_phone: secondaryContact ? secondaryContact.phone_number : null,
    alert_text: alertMessage,
    escalated_at: new Date().toISOString()
  }
}];
